ALTER TABLE public.facturas_ecf ADD COLUMN vinculo_por_linea boolean NOT NULL DEFAULT false;
ALTER TABLE public.facturas_ecf_lineas ADD COLUMN expediente_id uuid REFERENCES public.expedientes(id), ADD COLUMN transporte_id uuid REFERENCES public.transportes(id), ADD CONSTRAINT ecf_linea_un_destino CHECK (expediente_id IS NULL OR transporte_id IS NULL);
CREATE INDEX ecf_lineas_transporte ON public.facturas_ecf_lineas(transporte_id);
CREATE INDEX ecf_lineas_expediente ON public.facturas_ecf_lineas(expediente_id);
CREATE OR REPLACE FUNCTION public.importe_ecf_transporte(p_factura uuid,p_transporte uuid) RETURNS numeric LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT CASE WHEN f.vinculo_por_linea THEN COALESCE((SELECT sum(l.valor+COALESCE(l.itbis,0)) FROM public.facturas_ecf_lineas l WHERE l.factura_id=f.id AND l.transporte_id=p_transporte),0) ELSE f.monto_total END FROM public.facturas_ecf f WHERE f.id=p_factura AND f.eliminado_en IS NULL $$;
REVOKE ALL ON FUNCTION public.importe_ecf_transporte(uuid,uuid) FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.transporte_total_ecf_guardado() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF EXISTS(SELECT 1 FROM public.transporte_facturas_ecf WHERE transporte_id=NEW.id) THEN SELECT COALESCE(sum(public.importe_ecf_transporte(l.factura_ecf_id,NEW.id)),0) INTO NEW.ingreso_facturado FROM public.transporte_facturas_ecf l WHERE l.transporte_id=NEW.id; SELECT l.factura_ecf_id INTO NEW.factura_ecf_id FROM public.transporte_facturas_ecf l WHERE l.transporte_id=NEW.id ORDER BY l.created_at LIMIT 1; END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.transporte_ecf_total_editado() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE public.transportes SET ingreso_facturado=ingreso_facturado WHERE id IN(SELECT transporte_id FROM public.transporte_facturas_ecf WHERE factura_ecf_id=NEW.id); RETURN NULL; END $$;
CREATE OR REPLACE FUNCTION public.sincronizar_transporte_facturas_ecf() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_tid uuid:=COALESCE(NEW.transporte_id,OLD.transporte_id); v_f record; BEGIN SELECT f.id,f.encf,f.fecha_emision INTO v_f FROM public.transporte_facturas_ecf l JOIN public.facturas_ecf f ON f.id=l.factura_ecf_id AND f.eliminado_en IS NULL WHERE l.transporte_id=v_tid ORDER BY f.fecha_emision,l.created_at LIMIT 1; UPDATE public.transportes SET factura_ecf_id=v_f.id,ingreso_facturado=COALESCE((SELECT sum(public.importe_ecf_transporte(l.factura_ecf_id,v_tid)) FROM public.transporte_facturas_ecf l WHERE l.transporte_id=v_tid),0),factura_numero=COALESCE(v_f.encf,factura_numero),factura_fecha=COALESCE(v_f.fecha_emision,factura_fecha) WHERE id=v_tid; RETURN NULL; END $$;
CREATE OR REPLACE FUNCTION public.guardar_lineas_ecf(p_factura uuid,p_lineas jsonb,p_por_linea boolean) RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE j jsonb; n integer:=0; v_id uuid; v_exp uuid; v_tr uuid; BEGIN IF jsonb_typeof(p_lineas)<>'array' OR jsonb_array_length(p_lineas)=0 THEN RAISE EXCEPTION 'La factura requiere renglones'; END IF; PERFORM 1 FROM public.facturas_ecf WHERE id=p_factura AND eliminado_en IS NULL FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Factura no disponible'; END IF; FOR j IN SELECT value FROM jsonb_array_elements(p_lineas) LOOP n:=n+1; v_exp:=NULLIF(j->>'expediente_id','')::uuid; v_tr:=NULLIF(j->>'transporte_id','')::uuid; IF v_exp IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.expedientes WHERE id=v_exp AND eliminado_en IS NULL) THEN RAISE EXCEPTION 'Expediente no disponible'; END IF; IF v_tr IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.transportes WHERE id=v_tr AND eliminado_en IS NULL) THEN RAISE EXCEPTION 'Transporte no disponible'; END IF; SELECT id INTO v_id FROM public.facturas_ecf_lineas WHERE factura_id=p_factura AND orden=n LIMIT 1; IF v_id IS NULL THEN INSERT INTO public.facturas_ecf_lineas(factura_id,orden) VALUES(p_factura,n) RETURNING id INTO v_id; END IF; UPDATE public.facturas_ecf_lineas SET cantidad=(j->>'cantidad')::numeric,descripcion=j->>'descripcion',unidad=j->>'unidad',precio=(j->>'precio')::numeric,itbis=(j->>'itbis')::numeric,descuento=(j->>'descuento')::numeric,recargo=(j->>'recargo')::numeric,valor=(j->>'valor')::numeric,gravado=(j->>'gravado')::boolean,expediente_id=v_exp,transporte_id=v_tr WHERE id=v_id; END LOOP; DELETE FROM public.facturas_ecf_lineas WHERE factura_id=p_factura AND orden>n; UPDATE public.facturas_ecf SET vinculo_por_linea=p_por_linea WHERE id=p_factura; IF p_por_linea THEN DELETE FROM public.transporte_facturas_ecf WHERE factura_ecf_id=p_factura AND transporte_id NOT IN(SELECT transporte_id FROM public.facturas_ecf_lineas WHERE factura_id=p_factura AND transporte_id IS NOT NULL); INSERT INTO public.transporte_facturas_ecf(transporte_id,factura_ecf_id,created_by) SELECT DISTINCT transporte_id,p_factura,auth.uid() FROM public.facturas_ecf_lineas WHERE factura_id=p_factura AND transporte_id IS NOT NULL ON CONFLICT DO NOTHING; UPDATE public.transportes SET ingreso_facturado=ingreso_facturado WHERE id IN(SELECT transporte_id FROM public.transporte_facturas_ecf WHERE factura_ecf_id=p_factura); END IF; END $$;
REVOKE ALL ON FUNCTION public.guardar_lineas_ecf(uuid,jsonb,boolean) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.guardar_lineas_ecf(uuid,jsonb,boolean) TO authenticated;
COMMENT ON COLUMN public.facturas_ecf.vinculo_por_linea IS 'Separates fiscal line destinations; invoice face total remains unchanged.';